import assert from "node:assert/strict";
import { test } from "node:test";

import { sanitizeIgesGlobal, sanitizeParasolidHeader, sanitizeStepHeader } from "./operations.ts";

// G4: the native exporters write the staging path and the OS user name into the file header.

const STAGING = "/Users/jane.doe/work/models/.plasticity-step-AbC123/geometry.step";
const stepFile = (name: string, author: string, organisation: string) => [
  "ISO-10303-21;", "HEADER;", "", "/* File generated by HOOPS Exchange Version 25.8.0 */", "",
  "FILE_DESCRIPTION(('HOOPS Exchange Step'),'2;1');", "",
  `FILE_NAME('${name}',`, "'2026-11-16T16:08:24-07:00',", `('${author}'),`, `('${organisation}'),`, "'HOOPS Exchange 2025.8',", "'HOOPS Exchange',", "'Unknown authorisation');", "",
  "FILE_SCHEMA( ('AP203_CONFIGURATION_CONTROLLED_3D_DESIGN_OF_MECHANICAL_PARTS_AND_ASSEMBLIES_MIM_LF') );", "", "ENDSEC;", "", "DATA;",
  "#1=PRODUCT('jane.doe','/Users/jane.doe/data note','',(#2));", "#2=PRODUCT_CONTEXT('',#3,'mechanical');", "ENDSEC;", "END-ISO-10303-21;", "",
].join("\n");

test("STEP header: name is the output base name, author and organisation are empty, the data section is byte-identical", () => {
  const input = stepFile(STAGING, "jane.doe", "Unknown organisation");
  const output = sanitizeStepHeader(input, "box.step");
  assert.match(output, /FILE_NAME\('box\.step',\n'2026-11-16T16:08:24-07:00',\n\(''\),\n\(''\),\n'HOOPS Exchange 2025\.8',\n'HOOPS Exchange',\n'Unknown authorisation'\);/);
  assert.equal(output.slice(output.indexOf("DATA;")), input.slice(input.indexOf("DATA;")), "data section unchanged, including text that names the user");
  assert.equal(output.slice(0, output.indexOf("FILE_NAME(")), input.slice(0, input.indexOf("FILE_NAME(")));
  assert.equal(output.includes("jane.doe/work"), false);
  assert.equal(output.slice(0, output.indexOf("DATA;")).includes("jane.doe"), false);
});

test("STEP header: quotes in names are escaped and a header without FILE_NAME is left alone", () => {
  assert.match(sanitizeStepHeader(stepFile(STAGING, "a", "b"), "it's.step"), /FILE_NAME\('it''s\.step',/);
  assert.match(sanitizeStepHeader(stepFile("x", "a", "b"), "naïve.step"), /FILE_NAME\('na\\X2\\00EF\\X0\\ve\.step',/);
  const bare = "ISO-10303-21;\nHEADER;\nENDSEC;\nDATA;\nENDSEC;\nEND-ISO-10303-21;\n";
  assert.equal(sanitizeStepHeader(bare, "a.step"), bare);
  // Commas, parentheses and doubled quotes inside the quoted values do not end an argument.
  const odd = stepFile("n''(x),(1)", "a,b)", "c,(d");
  const cleaned = sanitizeStepHeader(odd, "k.step");
  assert.match(cleaned, /FILE_NAME\('k\.step',\n'2026-11-16T16:08:24-07:00',\n\(''\),\n\(''\),\n'HOOPS Exchange 2025\.8',/);
});

// IGES: 80-column records, section letter in column 73, the Global section wrapped at column 72.
const igesRecord = (text: string, letter: string, sequence: number) => `${text.padEnd(72, " ")}${letter}${String(sequence).padStart(7, " ")}`;
function igesFile(globalText: string): { text: string; lines: string[]; startLines: string[]; rest: string[] } {
  const startLines = [igesRecord("", "S", 1), igesRecord("File generated by HOOPS Exchange Version 25.8.0", "S", 2)];
  const globals: string[] = [];
  for (let offset = 0; offset < globalText.length; offset += 72) globals.push(igesRecord(globalText.slice(offset, offset + 72), "G", globals.length + 1));
  const rest = [
    `${"     502".padEnd(8)}       1       1       0   65535       0       0       000010001D      1`,
    `     502    1000       0       2       1                Solid 27       0D      2`,
    igesRecord("502,1,10HSolid 2711,0,0;", "P", 1),
  ];
  const terminate = `S${String(startLines.length).padStart(7, " ")}G${String(globals.length).padStart(7, " ")}D${String(2).padStart(7, " ")}P${String(1).padStart(7, " ")}`.padEnd(72, " ") + "T      1";
  const lines = [...startLines, ...globals, ...rest, terminate];
  return { text: lines.join("\n") + "\n", lines, startLines, rest };
}

test("IGES Global section: file name becomes the output base name, lines re-wrap, other sections and the T record stay", () => {
  const path = "/Users/jane.doe/work/models/.plasticity-iges-0rFz85/geometry.igs";
  const globalText = `1H,,1H;,,${path.length}H${path},14HHOOPS Exchange,6H25.8.0,32,24,8,56,15,,1.,2,2HMM,1000,1.,13H261116.160824,1D-05,1000000.,,,9,0,13H261116.160824;`;
  const input = igesFile(globalText);
  assert.ok(input.lines.filter((line) => line[72] === "G").length >= 3);
  const output = sanitizeIgesGlobal(input.text, "box.igs");
  const lines = output.split("\n");
  const globalsOut = lines.filter((line) => line[72] === "G");
  const stream = globalsOut.map((line) => line.slice(0, 72)).join("").trimEnd();
  assert.equal(stream, "1H,,1H;,,7Hbox.igs,14HHOOPS Exchange,6H25.8.0,32,24,8,56,15,,1.,2,2HMM,1000,1.,13H261116.160824,1D-05,1000000.,,,9,0,13H261116.160824;");
  assert.deepEqual(globalsOut.map((line) => line.slice(72)), globalsOut.map((_, index) => `G${String(index + 1).padStart(7, " ")}`));
  assert.ok(globalsOut.every((line) => line.length === 80));
  assert.deepEqual(lines.filter((line) => line[72] === "S"), input.startLines);
  assert.deepEqual(lines.filter((line) => line[72] === "D" || line[72] === "P"), input.rest);
  const terminate = lines.find((line) => line[72] === "T")!;
  assert.equal(terminate.slice(0, 32), `S      2G${String(globalsOut.length).padStart(7, " ")}D      2P      1`);
  assert.equal(output.includes("jane.doe"), false);
  assert.equal(output.split("\n").join("").includes(path.slice(0, 20)), false);
});

test("IGES Global section it cannot parse is returned unchanged", () => {
  const input = igesFile("garbage without delimiters").text;
  assert.equal(sanitizeIgesGlobal(input, "box.igs"), input);
  assert.equal(sanitizeIgesGlobal(igesRecord("only a start line", "S", 1), "box.igs"), igesRecord("only a start line", "S", 1));
});

test("Parasolid header: KEY and FILE name the output, everything from END_OF_HEADER on is byte-identical, binary included", () => {
  const body = Buffer.concat([Buffer.from("**END_OF_HEADER" + "*".repeat(40) + "\n3: TRANSMIT FILE created by modeller version 3801167\n"), Buffer.from([0, 255, 128, 10, 59, 0x4b, 0x45, 0x59, 61])]);
  const header = (path: string) => Buffer.from(["**ABCDEFGHIJKLMNOPQRSTUVWXYZ**", "**PART1;", "MC=unknown;", "USER=unknown;", "FORMAT=binary;", `KEY=${path.replace(/\.x_b$/u, "")};`, `FILE=${path};`, "DATE=unknown;", "**PART2;", "SCH=SCH_3801167_38101;", ""].join("\n"), "latin1");
  const input = Buffer.concat([header("/Users/jane.doe/work/.plasticity-parasolid-xYz/geometry.x_b"), body]);
  const output = sanitizeParasolidHeader(input, "part.x_b");
  const text = output.subarray(0, output.indexOf("**END_OF_HEADER")).toString("latin1");
  assert.match(text, /\nKEY=part;\nFILE=part\.x_b;\nDATE=unknown;\n/);
  assert.ok(output.subarray(output.indexOf("**END_OF_HEADER")).equals(body));
  assert.equal(output.includes("jane.doe"), false);
  const noMarker = Buffer.from("no header marker");
  assert.equal(sanitizeParasolidHeader(noMarker, "a.x_t"), noMarker);
});
